const express = require('express');
const { SQSClient, ReceiveMessageCommand } = require('@aws-sdk/client-sqs');
const { JobRegistry } = require('../services/jobRegistry');

const app = express();

const sqs = new SQSClient({ region: 'us-west-1' });
const STATUS_QUEUE_URL = process.env.SQS_JOB_STATUS_QUEUE_URL;

app.get('/api/queue/jobs/:correlationId/status', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { correlationId } = req.params;

  // Confirm that the job correlation ID belongs to the caller's tenant
  const jobRecord = await JobRegistry.findByCorrelationId(correlationId);
  if (!jobRecord || jobRecord.tenantId !== req.user.tenantId) {
    return res.status(403).json({ error: 'Access denied: job record belongs to another tenant' });
  }

  const receiveCmd = new ReceiveMessageCommand({
    QueueUrl: STATUS_QUEUE_URL,
    MaxNumberOfMessages: 10,
    VisibilityTimeout: 0,
    MessageAttributeNames: ['All']
  });

  try {
    const data = await sqs.send(receiveCmd);
    const messages = data.Messages || [];

    const jobMsg = messages.find(m => {
      try {
        const parsed = JSON.parse(m.Body);
        return parsed.correlationId === correlationId;
      } catch {
        return false;
      }
    });

    if (!jobMsg) {
      return res.status(404).json({ error: 'Job status message not located in queue buffer' });
    }

    const payload = JSON.parse(jobMsg.Body);
    res.json({
      correlationId,
      status: payload.status,
      workerId: payload.workerId,
      enqueuedAt: payload.enqueuedAt
    });
  } catch (err) {
    res.status(500).json({ error: 'Failed to inspect job status' });
  }
});

app.listen(3005);
